'use strict';
// Local design prototype. No network writes, backend, storage, or real accounting.
const main=document.querySelector('#main');
const state={route:'daily',selected:0,detail:location.hash.endsWith('/detail'),edit:false,dailyStatus:'Draft',amount:12500,memo:'Printer paper and stationery',bank:'Petty cash',paid:2500,credit:0,apPaid:2000,purchase:'Ordered',taxInclusive:false,hidden:new Set(),setupStep:0,setup:{name:'Birch Studio',country:'Neutral',currency:'USD',legal:'Not sure yet',industry:'Professional services',records:'empty',target:'real'},cart:0,posPaid:false,notice:''};
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>{const sign=n<0?'-':'';n=Math.abs(n);return sign+Math.trunc(n/100).toLocaleString('en-US')+'.'+String(n%100).padStart(2,'0')};
const minor=s=>{if(!/^\d{1,9}(\.\d{1,2})?$/.test(String(s).trim()))throw Error('Enter a positive amount with up to two decimal places.');const [a,b='']=String(s).trim().split('.');return Number(a)*100+Number(b.padEnd(2,'0'))};
const button=(text,action,primary=false)=>`<button data-action="${action}" class="${primary?'primary':''}">${text}</button>`;
const badge=(text,type='')=>`<span class="badge ${type}">${text}</span>`;
const field=(label,name,value,type='text',help='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='text'?'autocomplete="off"':''}>${help?`<small>${help}</small>`:''}</label>`;
const select=(label,name,options,value)=>`<label class="field">${label}<select name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
const heading=(title,desc,actions='')=>`<div class="heading"><div><p class="eyebrow">${state.route==='setup'?'Business setup':'Primary book · USD'}</p><h1>${title}</h1><p>${desc}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
const notice=()=>state.notice?`<div class="notice" role="status" tabindex="-1" id="feedback">${esc(state.notice)}</div>`:'';
const ledger=(rows)=>`<div class="ledger" role="table" aria-label="Accounting effect"><div class="ledger-row head" role="row"><span role="columnheader">Account</span><span role="columnheader">Debit USD</span><span role="columnheader">Credit USD</span></div>${rows.map(([name,d,c])=>`<div class="ledger-row" role="row"><span role="cell">${name}</span><span role="cell">${d===null?'—':money(d)}</span><span role="cell">${c===null?'—':money(c)}</span></div>`).join('')}</div>`;
const summary=rows=>`<dl class="summary">${rows.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`;
const tabs=items=>`<div class="tabs">${items.map(([label,action,active])=>`<button data-action="${action}" aria-pressed="${!!active}">${label}</button>`).join('')}</div>`;
const annotations=(text)=>`<details class="state-example"><summary>Review notes for this workflow</summary><p class="small muted">${text}</p><a href="#notes">All acceptance criteria</a></details>`;
function daily(){
 const records=[['Harbor Office Supply','EXP-0018 · 14 Sep 2026',state.amount,state.dailyStatus],['Beacon Internet','EXP-0017 · 11 Sep 2026',6800,'Draft'],['Northline Rent','EXP-0016 · 8 Sep 2026',24000,'Draft'],['City Courier','EXP-0015 · 3 Sep 2026',3200,'Draft']];
 const r=records[state.selected];
 return heading('Transactions','Review a saved draft, then add it to the books.',button('Open sample expense','openExample',true))+notice()+`<div class="console ${state.detail?'show-detail':''}"><section class="list"><div class="bar"><label class="field" style="flex:1;margin:0">Search these records<input type="search" id="search" placeholder="Payee or reference"></label></div><div class="record-list">${records.map((r,i)=>`<button class="record ${i===state.selected?'selected':''}" data-action="record" data-index="${i}"><span>${r[0]}<small>${r[1]}</small></span><span class="money">${money(r[2])}<small>${r[3]}</small></span></button>`).join('')}</div><p class="small muted" style="margin-top:15px">4 records · one search · values are always shown</p></section><section class="detail panel"><button class="back" data-action="backList">Back to transactions</button><div class="detail-heading"><div><h2>${r[1].split(' · ')[0]}</h2><span>${r[0]}</span></div><div class="money"><div class="big">${money(r[2])}</div>${badge(r[3],r[3]==='Posted'?'good':'')}</div></div>${state.edit?`<form id="expense-form">${field('Amount (USD)','amount',money(state.amount).replaceAll(',',''),'text')}${select('Paid from','bank',['Cash and bank','Petty cash'],state.bank)}${field('Memo','memo',state.memo)}<p class="small muted">Saving preserves the selected cash account. It does not post to reports.</p><div class="actions">${button('Cancel','cancelEdit')}${button('Save draft','saveExpense',true)}</div></form>`:`${summary([['Date','14 September 2026'],['Paid from',state.selected===0?esc(state.bank):'Cash and bank'],['Category','Office supplies'],['Memo',state.selected===0?esc(state.memo):'Sample record']])}<h3>${r[3]==='Draft'?'Posting preview':'Accounting entry'}</h3>${ledger([['Office supplies',r[2],null],[state.selected===0?esc(state.bank):'Cash and bank',null,r[2]]])}<p class="small muted">${r[3]==='Draft'?'Posting increases expenses and reduces the selected cash account by the same amount.':'The original entry stays in history. A correction creates a linked reversal.'}</p><div class="actions end">${state.selected!==0?button('Open editable example','openExample'):r[3]==='Draft'?button('Edit draft','editExpense')+button('Post expense','postExpense',true):r[3]==='Posted'?button('Review correction','correctExpense'):button('Prepare replacement','repostExpense',true)}</div><details><summary>History and source</summary><p>Document EXP-0018 keeps its identity. ${state.dailyStatus==='Reversed'?'Posting 1 reversed on 16 September 2026.':''}</p><a href="#reports">Trace to reports</a></details>`}</section></div>`+annotations('Desktop keeps list and selected document together. Tablet and phone use list → detail → return, with amounts and status in both views. Save appears only while editing. Closed-period and permission checks belong to the existing server services; this prototype only demonstrates states.');
}
function parties(kind){
 const ar=kind==='customers',outstanding=ar?5250-state.paid-state.credit:5250-state.apPaid;
 return heading(ar?'Customers & receivables':'Suppliers & payables',ar?'Invoices, receipts and credits in one shared account.':'Bills, payments and credits in one shared account.',button(ar?'New invoice':'New bill','newDocument',true))+notice()+`<div class="metrics"><div class="metric"><span>Outstanding USD</span><strong>${money(outstanding)}</strong></div><div class="metric"><span>1–30 days overdue</span><strong>${money(outstanding)}</strong></div><div class="metric"><span>Reconciliation difference</span><strong>0.00</strong></div></div><div class="console ${state.detail?'show-detail':''}"><section class="list"><h2>${ar?'Customer invoices':'Supplier bills'}</h2><div class="record-list"><button class="record selected" data-action="openInvoice"><span>Sample customer and supplier<small>${ar?'INV-0024':'BILL-0011'} · Due 10 Sep 2026</small></span><span class="money">${money(outstanding)}<small>${outstanding===0?'Settled':'Part paid'}</small></span></button></div><details><summary>Party profile</summary><p>One party · Customer and supplier roles</p><p>Vetting: Draft · no enforcement in this preview</p></details><h3 style="margin-top:20px">Ageing at 16 Sep 2026</h3>${summary([['Current','0.00'],['1–30 days',money(outstanding)],['31–60 days','0.00'],['Over 60 days','0.00']])}</section><section class="detail panel"><button class="back" data-action="backList">Back to list</button><div class="detail-heading"><div><h2>${ar?'INV-0024':'BILL-0011'}</h2><p>Sample customer and supplier</p>${badge(outstanding===0?'Settled':'Part paid','good')}</div><div class="money"><span class="small muted">Outstanding USD</span><div class="big">${money(outstanding)}</div></div></div>${summary([['Net amount','50.00'],['DEMO5 · manual sample tax','2.50'],['Total','52.50'],[ar?'Receipts':'Payments',money(ar?state.paid:state.apPaid)],['Credits',money(ar?state.credit:0)]])}<h3>${ar?'Record a receipt':'Record a payment'}</h3><form id="payment-form"><div class="grid">${field('Amount (USD)','payment',money(Math.min(1000,outstanding)))}${field('Date','date','2026-09-16','date')}</div>${select(ar?'Received into':'Paid from','bank',['Cash and bank','Petty cash'],'Cash and bank')}${field('Reference','reference','PARTIAL-002')}<p class="small muted">USD document and USD cash account. No currency conversion is needed.</p><details><summary>Different currency or actual settlement rate</summary><p>Foreign-currency settlements require the booked base value, actual cash value and reviewed gain/loss mappings. This branch needs service validation before implementation.</p></details><div class="actions end">${ar?button('Review credit','credit'):''}<button class="primary" data-action="payment" ${outstanding===0?'disabled':''}>${ar?'Record receipt':'Record payment'}</button></div></form><div class="trace"><a href="#reports">View control-account reconciliation</a></div></section></div>`+annotations('Ordinary domestic payments omit irrelevant FX configuration. This requires a service change as well as conditional fields. Validate partial/over/duplicate allocations, credit limits, closed periods and cross-company IDs. Invoice and bill entry reuse one document pattern; Quotes remain outside core.');
}
const industries=['Professional services','Seasonal services','Retail shop','Wholesale / trader','Distributor','Restaurant / cafe','Membership club','Pharmacy','Jewelry','Light manufacturing','Service workshop'];
const countries=['Neutral','Pakistan','India','United Arab Emirates','United Kingdom','United States'];
const steps=['Business','Activities','Region','Chart','Past records','Confirm'];
function setup(){
 const s=state.setup;let body='';
 if(state.setupStep===0)body=`<div class="grid">${field('Business name','name',s.name)}${select('Country or neutral setup','country',countries,s.country)}${select('Base currency','currency',['USD','PKR','INR','AED','GBP'],s.currency)}${select('Legal form','legal',['Not sure yet','Sole proprietor','Partnership','Company','Nonprofit'],s.legal)}${field('Accounting start date','start',s.start||'2026-01-01','date')}${field('Fiscal year end','yearEnd',s.yearEnd||'2026-12-31','date')}</div><p class="small muted">Currency does not select a national chart or establish tax compliance. The base currency becomes fixed when the company is created.</p>`;
 if(state.setupStep===1)body=`${select('Primary industry','industry',industries,s.industry)}<fieldset><legend>Accounts you may need</legend>${['Stock held for sale','Customer credit','Supplier bills','Advance payments','Payroll-related accounts','Specialist manufacturing accounts'].map((x,i)=>`<label class="check"><input type="checkbox" name="cap${i}" ${state.setup['cap'+i]===undefined?(i===1||i===2?'checked':''):(state.setup['cap'+i]==='on'?'checked':'')}>${x}</label>`).join('')}</fieldset><p class="small muted">These answers recommend accounts. They do not activate specialist operations.</p>`;
 if(state.setupStep===2)body=`<h2>${esc(s.country)} package</h2>${s.country==='Neutral'?`<p>Continue with the existing neutral chart, or bring your own chart for review.</p>${badge('Neutral foundation')}`:`${badge('Research','warn')}<p style="margin-top:15px">The ${esc(s.country)} research is available for inspection. Accountant review and validation are pending; it cannot be installed into a real company.</p><p class="small muted">Review date: not approved · Country package version: not released</p>`}<div class="notice warn" style="margin-top:18px">No reviewed national package is available in this prototype. You can keep your country choice and continue with a neutral chart.</div>${select('Registration details','registration',['I am not sure yet','Keep details for later review'],s.registration||'I am not sure yet')}<p class="small muted">Uncertainty is not recorded as unregistered. Country-specific questions appear only after the package supports them.</p>`;
 const accounts=[['1000','Cash and bank','Required · cash_bank'],['1100','Receivables control','Required · receivables'],['2000','Payables control','Required · payables'],['3000','Owner equity','Required · equity'],['4000','Income','Required · income'],['5000','General expenses','Required · expense']];
 if(state.setupStep===3)body=`<div class="bar">${badge('Neutral chart · 6 accounts')}${badge('Industry recommendations · Research','warn')}</div><p>A deliberate minimal start. You can inspect researched industry suggestions, but those suggestions are not yet installation-ready.</p><details><summary>Inspect industry account suggestions</summary><p>${esc(s.industry)} ? Research</p><ul><li>Customer advances: liability until earned; recognition policy needs review.</li><li>Supplier advances: asset until applied to supported purchases.</li><li>Stock businesses: inventory, goods received awaiting bills and cost of sales, with reviewed stock-service mappings.</li></ul><p>These are candidate purposes, not installed accounts. Specialist capabilities require separate module review.</p></details>${accounts.map(([code,name,role],i)=>`<div class="account-row"><label><span class="small">Code</span><input name="code${i}" aria-label="${name} code" value="${s['code'+i]||code}"></label><label><span class="small">Display name</span><input name="account${i}" aria-label="${name} display name" value="${esc(s['account'+i]||name)}"></label><small>${role}<br>${i===0?'Where money is held':i===1?'Amounts customers owe':i===2?'Amounts owed to suppliers':i===3?'Owner investment and retained balance':i===4?'Sales and service income':'Day-to-day business costs'}</small></div>`).join('')}<details><summary>Accountant detail and provenance</summary><p>Existing source: core-starter-1.0.0.json · literal status: prerelease-foundation. Semantic keys stay independent of edited labels and codes. New catalogue status promotion is pending.</p><p>No regional package or tax mapping is installed. A future confirmation pins exact source hashes and immutable snapshots; this mock does not invent an installation receipt.</p></details>`;
 if(state.setupStep===4)body=`<fieldset><legend>How will you start?</legend>${[['empty','Start empty'],['chart','Import my existing chart'],['trial','Import opening trial balance'],['unpaid','Import unpaid customer / supplier documents']].map(([v,l])=>`<label class="check"><input type="radio" name="records" value="${v}" ${s.records===v?'checked':''}>${l}</label>`).join('')}</fieldset><div class="notice warn">Imports must be previewed and reconciled before confirmation. Unpaid documents explain the control balance; they must not post it a second time.</div><details><summary>Example of an unresolved match</summary><p>Receivables control: 1,250.00 · matched unpaid documents: 1,200.00 · difference: <strong>50.00</strong></p><p>Confirmation is blocked until the exact difference is resolved.</p></details>`;
 if(state.setupStep===5)body=`${summary([['Company',esc(s.name)],['Book / currency','Primary book / '+esc(s.currency)],['Country / industry',esc(s.country)+' / '+esc(s.industry)],['Chart','Neutral core-starter 1.0.0'],['Regional package','None installed'],['Role mappings','6 required mappings shown in chart step'],['Import work',s.records==='empty'?'None selected':'Pending preview and reconciliation']])}<div class="notice warn">This is a design review. No company will be created. The future confirmation must display real package hashes, detect stale previews and prevent duplicate installation.</div><label class="check"><input type="checkbox" id="setup-ack">I understand this is accounting setup, not tax filing approval.</label>`;
 return heading('Set up your business','Choose an accounting starting point explicitly. Sample businesses have a separate chooser.',`<a class="button" href="#samples">Try a sample instead</a>`)+notice()+`<div class="setup"><div class="steps">${steps.map((s,i)=>`<span ${state.setupStep===i?'aria-current="step"':''}>${i+1}. ${s}</span>`).join('')}</div><section class="panel"><h2>${state.setupStep+1}. ${steps[state.setupStep]}</h2><form id="setup-form">${body}</form><div class="foot-actions">${state.setupStep?button('Back','setupBack'):''}${button(state.setupStep===5?'Finish design walkthrough':'Continue','setupNext',true)}</div></section></div>`;
}
function purchasing(){const received=state.purchase!=='Ordered',billed=state.purchase==='Billed';return heading('Purchasing','Receive what arrived, then review the supplier bill.')+notice()+`<div class="console ${state.detail?'show-detail':''}"><section class="list"><h2>Purchase orders</h2><div class="record-list"><button class="record selected" data-action="openInvoice"><span>PO-0012 · Harbor Supply<small>5 notebooks · 10.00 each</small></span><span class="money">50.00<small>${state.purchase}</small></span></button></div></section><section class="detail panel"><button class="back" data-action="backList">Back to list</button><div class="detail-heading"><h2>PO-0012</h2>${badge(state.purchase,billed?'good':'')}</div>${summary([['Ordered quantity','5'],['Received quantity',received?'5':'0'],['Net price','50.00'],['Goods awaiting bills',received&&!billed?'50.00':'0.00']])}<h3>${!received?'Receive goods':!billed?'Review supplier bill':'Receipt matched to bill'}</h3>${!received?`<p>Five notebooks arrived in the Main stock location.</p>${ledger([['Inventory',5000,null],['Goods received awaiting bills',null,5000]])}${button('Receive 5 items','receive',true)}`:!billed?`${summary([['Bill net','50.00'],['DEMO5 input tax','2.50'],['Payable','52.50'],['Quantity / net price difference','0 / 0.00']])}${ledger([['Goods received awaiting bills',5000,null],['Input tax',250,null],['Payables',null,5250]])}${button('Post matched bill','bill',true)}`:`<div class="notice">No unmatched receipt balance. The bill is available in shared Payables.</div><a href="#suppliers/detail" class="button primary">Open supplier bill</a>`}</section></div>`+annotations('Order, receipt and bill have distinct accounting consequences. Qty/price mismatches need explicit review. Duplicate receiving, negative stock, permissions and period locks remain service requirements. LC, landed costs and advanced warehouse flows are plugins.');}
function inventory(){return heading('Inventory','Basic quantities and carrying value, with a path back to each movement.')+notice()+`<div class="metrics"><div class="metric"><span>Notebooks · quantity on hand</span><strong>3</strong></div><div class="metric"><span>Carrying value USD</span><strong>30.00</strong></div><div class="metric"><span>Stock / GL difference</span><strong>0.00</strong></div></div><section class="panel"><h2>Movement history · Main stock</h2><div class="table-scroll mobile-cards"><table><thead><tr><th>Source</th><th>Quantity</th><th>Value USD</th><th>Balance</th></tr></thead><tbody>${[['Receipt GR-0012','+5','50.00','5'],['Invoice INV-0024','−2','−20.00','3']].map(r=>`<tr>${r.map((x,i)=>`<td data-label="${['Source','Quantity','Value USD','Balance'][i]}">${i===0?`<a href="#${r[0].startsWith('Receipt')?'purchasing':'customers'}/detail">${x}</a>`:x}</td>`).join('')}</tr>`).join('')}</tbody></table></div><details><summary>Review a stock count</summary><p>Book quantity 3 · counted quantity 2 · difference −1, carrying value −10.00.</p><p>A reviewed adjustment needs a reason and expense account before posting.</p>${button('Show count review','count')}</details></section>`+annotations('Every mobile row retains quantity, value and source. Stock receipts/issues/counts use existing valuation services. Batch, expiry, prescription controls, recipes, jewelry purity and manufacturing execution are not implied by product accounts.');}
function tax(){return heading('Tax settings','Owner-maintained codes and effective dates. Country packs add reviewed rules.')+notice()+`<div class="grid"><section class="panel"><h2>Price display</h2><form id="tax-form">${select('Default line prices','prices',['Tax exclusive','Tax inclusive'],state.taxInclusive?'Tax inclusive':'Tax exclusive')}<p class="small muted">Documents retain their chosen tax basis. Changing this default must not recalculate posted history.</p><h3>Example · DEMO5</h3>${summary(state.taxInclusive?[['Entered gross','105.00'],['Net','100.00'],['Tax','5.00']]:[['Entered net','100.00'],['Tax','5.00'],['Total','105.00']])}${button('Save default','saveTax',true)}</form></section><section class="panel"><h2>DEMO5</h2>${badge('Manual sample rate','warn')}${summary([['Rate','5%'],['Effective from','1 January 2026'],['Sales mapping','Output tax liability'],['Purchase mapping','Input tax asset']])}<p class="small muted">This example is not a country tax rule. No forms, e-filing or provider submission is included.</p></section></div>`+annotations('Preserve exact rounding and dated tax-rate snapshots. Inclusive and exclusive modes are explicit settings. Country selection alone never implies compliance. Tax-code editing and additional effective dates reuse existing backend validation.');}
function modules(){return heading('Modules & visibility','Keep the core available and hide work you do not use.')+notice()+`<section class="panel"><h2>Accounting core</h2><p>Invoices, bills, partial payments, credits, ageing and reports share the same core.</p>${badge('Always available','good')}<h3 style="margin-top:24px">Show in navigation</h3><form id="modules-form">${['customers','suppliers','purchasing','inventory'].map(x=>`<label class="check"><input name="${x}" type="checkbox" ${state.hidden.has(x)?'':'checked'}>${x[0].toUpperCase()+x.slice(1)}</label>`).join('')}<p class="small muted">Hiding changes your navigation. It leaves posted history readable and does not deactivate the module.</p>${button('Save visibility','saveModules',true)}</form><details><summary>Activation and dependencies</summary><p>Deactivation is a separate permissioned action. Show open orders, stock and document dependencies before confirming it. Historical reads remain available.</p></details></section>`+annotations('Visibility and activation are separate controls. Vertical modules reuse core AR/AP. Quotes, batch/expiry, landed cost, LC flows and country filing are plugins. No dependency bypass is simulated here.');}
function reports(){return heading('Reports & reconciliation','Follow a figure from the report to its account and source.')+notice()+`<div class="bar"><label class="field">From<input type="date" value="${state.reportDates?.[0]||'2026-09-01'}" id="report-from"></label><label class="field">Through<input type="date" value="${state.reportDates?.[1]||'2026-09-16'}" id="report-to"></label>${button('Apply dates','reportDates')}</div><div class="grid"><section class="panel"><h2>Profit and loss · example</h2>${summary([['Income','50.00'],['Cost of sales','20.00'],['Gross profit','30.00']])}<button data-action="drill">Open income account</button><p class="small muted" style="margin-top:14px">Snapshot for the purchase/sale exercise. It does not aggregate other prototype exercises.</p></section><section class="panel"><h2>Control reconciliation</h2>${summary([['Receivables / open documents',money(5250-state.paid-state.credit)],['Payables / open documents',money(5250-state.apPaid)],['Inventory / movement value','30.00'],['Difference','0.00']])}<div class="actions"><a href="#customers/detail">Customer documents</a><a href="#suppliers/detail">Supplier documents</a></div></section></div><section class="panel" style="margin-top:18px"><h2>Bank reconciliation</h2><p>Statement receipt 25.00 · candidate customer receipt 25.00 · date 15 Sep 2026</p>${button('Review proposed match','bankMatch')}<details><summary>Balance sheet and trial balance pattern</summary><p>Use the same date controls, indented account groups, persistent currency and source links. On phones each row keeps debit and credit visible. Export, full statement matching and closing need populated acceptance fixtures.</p></details></section>`+annotations('Filters must survive report → account → source → back. Reconciliation uses authoritative ledgers, not duplicated balances. This page illustrates that hierarchy; production report calculations remain in existing services.');}
const samples=[['Cedar Studio','Professional services'],['Sunrise Garden Services','Seasonal services'],['Willow Corner Shop','Retail'],['Harbour Trade','Wholesale / trader'],['Harbor Supply Company','Distributor'],['Cedar Table','Restaurant'],['Riverside Community Club','Membership club'],['Meadow Training Pharmacy','Non-medicinal training stock'],['Lantern Finch Jewelry Studio','Jewelry'],['Maple Bench Works','Light manufacturing'],['Wheel & Spoke Workshop','Customer-owned property separate']];
function samplesPage(){return heading('Explore sample companies','Fictional records stay in separate sample books. They never enter your business.')+`<div class="notice warn">Proposed eleven-company programme · 2024 and 2025 history, with 2026 for practice. Expansion and reconciliation are pending; these are design previews.</div><div class="grid three">${samples.map(([n,d],i)=>`<article class="panel tile"><span class="eyebrow">Sample preview</span><h2>${n}</h2><p>${d}</p><span class="small muted">Two-year history planned · not yet loadable</span><button data-action="sample" data-index="${i}">Preview exercises</button></article>`).join('')}</div>`+annotations('Separate entry from real setup. Future loader creates a new isolated company only, is transactional/idempotent and reconciles every pack. Existing 4 historical and 7 one-month families must converge; current public 100-record capacity needs an explicit policy for deep histories.');}
function pos(){return heading('Point of sale','A short cash-sale journey for an isolated sample.')+notice()+`<div class="grid"><section class="panel"><h2>Products</h2><p>Training notebook · USD 4.50</p>${button('Add notebook','addCart',true)}<p class="small muted" style="margin-top:20px">Sample cash-sale example only.</p></section><section class="panel"><h2>${state.posPaid?'Receipt POS-0031':'Current sale'}</h2>${state.cart?`${summary([['Notebooks',String(state.cart)],['Total USD',money(state.cart*450)]])}${state.posPaid?`<div class="notice">Cash sale recorded in this design walkthrough.</div><a href="#reports">View accounting source pattern</a>`:`${field('Cash received (USD)','cash',money(state.cart*450))}<div class="actions">${button('Remove one','removeCart')}${button('Record cash sale','posPay',true)}</div>`}`:`<div class="empty">Your cart is empty. Choose a product to start.</div>`}</section></div>`+annotations('Cart, review and receipt remain distinct. Mobile must keep total, tender, change and primary action visible without overlaying content. No card/provider payment is simulated.');}
function notes(){return heading('One system, eight workflow lanes','A proposed refinement of the approved Review Console, grounded in the route audit.')+`<section class="panel"><h2>Shared interaction rules</h2><ul class="note-list"><li>One compact header contains company, book, currency and sample identity. One navigation list scales with enabled modules.</li><li>One page title, one primary action, and one current document status. Secondary journal/history detail is progressive.</li><li>Desktop list/detail becomes a deliberate list-to-detail journey on smaller screens. Amounts, debit/credit and status never disappear.</li><li>Draft → review → post uses an explicit accounting preview. Corrections retain document identity and link dated reversals.</li><li>Errors preserve entered values and identify the exact field. Success names the result; loading marks pending work and prevents double submission.</li><li>All financial writes continue through existing services with company scope, CSRF, permissions, transactions and durable duplicate protection.</li></ul></section><section class="panel"><h2>Implementation acceptance</h2><ol class="note-list"><li>Accept catalogue contract and six-step setup. Do not implement a migration until that gate is passed.</li><li>Review source provenance, semantic roles and exact accounting examples. No regional package is Released yet.</li><li>Reconcile all eleven deterministic packs before a transactional isolated loader is shipped.</li><li>Apply the shared shell, then setup/migration, daily, customer/supplier, purchasing/inventory, tax/admin, reports and POS/sample lanes.</li><li>Test keyboard, focus, labels, contrast, zoom, reduced motion, touch, validation recovery and every source-to-report path. Screenshots alone do not establish WCAG 2.2 AA.</li></ol></section><section class="panel"><h2>State examples</h2><div class="actions">${button('Show validation error','exampleError')}${button('Show loading / success','exampleLoading')}${button('Show empty result','exampleEmpty')}</div><div id="state-example" style="margin-top:15px"></div></section>`;}
function render(focus=false){
 state.route=location.hash.slice(1).split('/')[0]||'daily';const routes={daily,customers:()=>parties('customers'),suppliers:()=>parties('suppliers'),setup,purchasing,inventory,tax,modules,reports,samples:samplesPage,pos,notes};
 main.innerHTML=(routes[state.route]||notes)();document.title=(main.querySelector('h1')?.textContent||'Review')+' · PHP Ledger design';
 document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+state.route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');a.hidden=!!a.dataset.module&&state.hidden.has(a.dataset.module)});
 if(focus)main.focus();
}
function announce(text){state.notice=text;render();document.querySelector('#feedback')?.focus();}
function error(text,form){let box=form.querySelector('.error');if(!box){box=document.createElement('div');box.className='notice error';box.setAttribute('role','alert');box.tabIndex=-1;form.prepend(box)}box.textContent=text;box.focus();}
document.querySelector('#menu').onclick=e=>{const open=document.querySelector('nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));};
document.querySelector('.skip').onclick=e=>{e.preventDefault();main.focus();main.scrollIntoView({block:'start'});};
document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('input',e=>{if(e.target.id==='search'){const q=e.target.value.toLowerCase();document.querySelectorAll('.record').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(q));}});
document.addEventListener('click',async e=>{
 const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action;state.notice='';
 if(a==='record'){state.selected=Number(b.dataset.index);state.detail=true;state.edit=false;render();main.querySelector('.detail')?.scrollIntoView({block:'start'});return;}
 if(a==='openInvoice'){state.detail=true;render();return;}
 if(a==='backList'){state.detail=false;render();return;}
 if(a==='openExample'){state.selected=0;state.detail=true;state.edit=false;render();return;}
 if(a==='editExpense'){state.selected=0;state.detail=true;state.edit=true;render();return;}
 if(a==='cancelEdit'){state.edit=false;render();return;}
 if(a==='saveExpense'){const f=document.querySelector('#expense-form');try{const v=minor(f.amount.value);if(v<=0)throw Error('Amount must be greater than zero.');state.amount=v;state.bank=f.bank.value;state.memo=f.memo.value;state.edit=false;announce('Draft saved. Paid-from account retained: '+state.bank+'.')}catch(err){error(err.message,f)}return;}
 if(a==='postExpense'){if(state.selected!==0){state.selected=0;state.detail=true;announce('This walkthrough posts EXP-0018. Review its values before posting.');return;}state.dailyStatus='Posted';announce('EXP-0018 posted in this simulated walkthrough. Original history is retained.');return;}
 if(a==='correctExpense'){main.querySelector('.detail').innerHTML=`<h2>Reverse EXP-0018</h2><p>The document number stays EXP-0018. A dated reversal cancels the original accounting entry.</p>${field('Reversal date','reversalDate','2026-09-16','date')}${ledger([[esc(state.bank),state.amount,null],['Office supplies',null,state.amount]])}<p class="small muted">Backdating requires permission and an open period.</p><div class="actions">${button('Cancel','cancelCorrection')}${button('Confirm linked reversal','confirmCorrection',true)}</div>`;return;}
 if(a==='cancelCorrection'){render();return;}
 if(a==='confirmCorrection'){state.dailyStatus='Reversed';announce('Posting 1 reversed under EXP-0018. Prepare a replacement under the same document identity.');return;}
 if(a==='repostExpense'){state.dailyStatus='Draft';state.edit=true;render();return;}
 if(a==='payment'){const f=document.querySelector('#payment-form');try{const value=minor(f.payment.value),ar=state.route==='customers',remaining=ar?5250-state.paid-state.credit:5250-state.apPaid;if(value<=0||value>remaining)throw Error('Enter an amount greater than zero and no more than '+money(remaining)+'.');if(!f.reference.value.trim())throw Error('Enter a receipt or payment reference.');if(ar)state.paid+=value;else state.apPaid+=value;announce((ar?'Receipt':'Payment')+' of '+money(value)+' recorded in this example. Outstanding balance updated.')}catch(err){error(err.message,f)}return;}
 if(a==='credit'){const value=Math.min(500,5250-state.paid-state.credit);if(!value){announce('No unallocated amount remains in this example.');return;}main.querySelector('.detail').innerHTML=`<h2>Review linked credit</h2><p>INV-0024 · credit ${money(value)} · available ${money(5250-state.paid-state.credit)}</p><p>This credit reduces the original receivable and retains its source relationship.</p><div class="actions">${button('Cancel','cancelCorrection')}${button('Post linked credit','confirmCredit',true)}</div>`;return;}
 if(a==='confirmCredit'){state.credit+=Math.min(500,5250-state.paid-state.credit);announce('Linked credit recorded in the simulated customer account.');return;}
 if(a==='newDocument'){main.innerHTML=heading(state.route==='customers'?'New invoice':'New bill','One document pattern with explicit tax basis.')+`<form id="document-form" class="panel">${select('Party','party',['Sample customer and supplier'],'Sample customer and supplier')}${field('Description','description','Sample service')}${field('Line net amount (USD)','net','50.00')}${select('Price basis','basis',['Tax exclusive','Tax inclusive'],state.taxInclusive?'Tax inclusive':'Tax exclusive')}<p>DEMO5 is a sample manual rate. This walkthrough uses a 52.50 example total.</p><div class="actions">${button('Cancel','cancelCorrection')}${button('Save and review example','documentReview',true)}</div></form>`;return;}
 if(a==='documentReview'){const f=document.querySelector('#document-form');try{const entered=minor(f.net.value);if(entered<=0)throw Error('Enter a positive line amount.');const inclusive=f.basis.value==='Tax inclusive',net=inclusive?Math.floor((entered*100+52)/105):entered,tax=inclusive?entered-net:Math.floor((net*5+50)/100);state.newDocument={description:f.description.value,net,tax,total:net+tax,basis:f.basis.value};main.innerHTML=heading('Review draft','Your entered values are retained before posting.')+`<section class="panel"><h2>${esc(state.newDocument.description)}</h2>${summary([['Party','Sample customer and supplier'],['Price basis',esc(state.newDocument.basis)],['Net',money(net)],['Tax ? DEMO5',money(tax)],['Total USD',money(net+tax)]])}<div class="actions">${button('Return to account','cancelCorrection')}${button('Post example document','postExampleDocument',true)}</div></section>`;}catch(err){error(err.message,f)}return;}
 if(a==='postExampleDocument'){main.innerHTML=heading('Example document posted','Simulated result in this tab only.')+`<section class="panel"><h2>${esc(state.newDocument.description)}</h2>${summary([['Net',money(state.newDocument.net)],['Tax',money(state.newDocument.tax)],['Outstanding USD',money(state.newDocument.total)]])}<p>The original part-paid exercise remains separate.</p>${button('Return to account exercise','cancelCorrection',true)}</section>`;return;}
 if(a==='setupBack'||a==='setupNext'){const f=document.querySelector('#setup-form');new FormData(f).forEach((v,k)=>state.setup[k]=v);if(state.setupStep===1)for(let i=0;i<6;i++)state.setup['cap'+i]=f['cap'+i].checked?'on':'off';if(a==='setupNext'&&state.setupStep===0&&!state.setup.name.trim()){error('Enter the business name. Your other choices are retained.',f);return;}if(a==='setupNext'&&state.setupStep===5){if(!document.querySelector('#setup-ack').checked){error('Confirm the accounting-setup acknowledgement to finish this walkthrough.',f);return;}announce('Design walkthrough complete. No company, account or journal was created.');return;}state.setupStep+=a==='setupNext'?1:-1;render(true);return;}
 if(a==='receive'){state.purchase='Received';announce('Five items received in this example. Review the supplier bill next.');return;}
 if(a==='bill'){state.purchase='Billed';announce('Bill matched in this example. Goods awaiting bills balance is zero.');return;}
 if(a==='count'){announce('Count review: reduce quantity by 1 and value by 10.00. A reason and inventory-adjustment account are required before any real posting.');return;}
 if(a==='saveTax'){state.taxInclusive=document.querySelector('[name=prices]').value==='Tax inclusive';announce('Default saved in this tab. Posted documents keep their original tax basis.');return;}
 if(a==='saveModules'){const f=document.querySelector('#modules-form');for(const x of ['customers','suppliers','purchasing','inventory']){if(f[x].checked)state.hidden.delete(x);else state.hidden.add(x)}announce('Navigation visibility updated. Historical documents remain readable.');return;}
 if(a==='reportDates'){const from=document.querySelector('#report-from').value,to=document.querySelector('#report-to').value;if(from>to){error('From must be on or before Through.',main);return;}state.reportDates=[from,to];announce('Date selection retained for drill-down: '+from+' through '+to+'. Figures remain the labelled example snapshot.');return;}
 if(a==='drill'){const dates=state.reportDates||['2026-09-01','2026-09-16'];main.innerHTML=heading('Income account','Date range retained: '+dates.join(' through '))+`<section class="panel">${ledger([['INV-0024 · Sample customer',null,5000]])}<a class="button primary" href="#customers/detail">Open source invoice</a><a class="button" href="#reports">Back to reports</a></section>`;return;}
 if(a==='bankMatch'){main.insertAdjacentHTML('beforeend',`<section class="panel"><h2>Match review</h2>${summary([['Statement receipt','25.00'],['Recorded customer receipt','25.00'],['Difference','0.00']])}<p>This design example contains no uploaded bank data. Matching and finalisation need a populated service test.</p>${button('Keep proposed match','confirmMatch',true)}</section>`);return;}
 if(a==='confirmMatch'){announce('Proposed match retained in this tab. No statement or ledger was changed.');return;}
 if(a==='sample'){const [n,d]=samples[Number(b.dataset.index)];document.querySelector('#company-name').textContent=n;main.innerHTML=heading(n,d+' · isolated sample design preview')+`<div class="notice warn">Research fixture plan. No company was loaded.</div><section class="panel"><h2>Choose an exercise</h2><div class="stack"><a href="#customers">Invoice, partial receipt and ageing</a><a href="#suppliers">Bill and partial payment</a><a href="#daily">Draft, review and linked reversal</a><a href="#reports">Trace a report to its source</a><a href="#samples">Return to all eleven sample plans</a></div><details><summary>History and unsupported operations</summary><p>Two closed historical years and an open practice year are planned. Specialist workflows remain outside this base; a chart account is not evidence of a working vertical module.</p></details></section>`;return;}
 if(a==='addCart'){state.cart++;state.posPaid=false;render();return;}
 if(a==='removeCart'){state.cart=Math.max(0,state.cart-1);render();return;}
 if(a==='posPay'){try{const cash=minor(document.querySelector('[name=cash]').value);if(cash<state.cart*450)throw Error('Cash received must cover '+money(state.cart*450)+'.');state.posPaid=true;announce('Cash received '+money(cash)+'. Change '+money(cash-state.cart*450)+'. Simulated receipt only.')}catch(err){error(err.message,main.querySelectorAll('.panel')[1])}return;}
 if(a==='exampleError'){document.querySelector('#state-example').innerHTML='<div class="notice error" role="alert" tabindex="-1">Amount is required. Enter the amount; the selected party and date are retained.</div>';document.querySelector('#state-example .notice').focus();return;}
 if(a==='exampleEmpty'){document.querySelector('#state-example').innerHTML='<div class="empty"><h3>No records match these filters</h3><p>Keep the current company and clear only your filters.</p><button data-action="exampleReset">Clear filters</button></div>';return;}
 if(a==='exampleReset'){document.querySelector('#state-example').innerHTML='<div class="notice" role="status">Filters cleared. Your company selection is unchanged.</div>';return;}
 if(a==='exampleLoading'){b.disabled=true;const host=document.querySelector('#state-example');host.setAttribute('aria-busy','true');host.innerHTML='<p role="status">Preparing preview…</p>';await new Promise(r=>setTimeout(r,650));if(!host.isConnected)return;host.removeAttribute('aria-busy');host.innerHTML='<div class="notice" role="status">Preview ready. Review before confirming.</div>';b.disabled=false;return;}
});
window.addEventListener('hashchange',()=>{state.notice='';state.edit=false;state.detail=location.hash.endsWith('/detail');document.querySelector('nav').classList.remove('open');document.querySelector('#menu').setAttribute('aria-expanded','false');render(true)});
render();
